for name in all_names:
    count = outline_text.count(name)
    status = "✅" if count > 0 else "❌"
    print(f"  {status} {name}: {count} mentions")

# Check all scene_sequences have 8 required fields
required_fields = ['scene_number', 'scene_location', 'characters_present', 
                   'scene_purpose', 'core_action', 'conflict_point', 
                   'emotional_shift', 'scene_outcome']

issues = []
for act_name in ['act_one', 'act_two', 'act_three']:
    for ch in outline[act_name]['key_chapters']:
        for scene in ch['scene_sequence']:
            for field in required_fields:
                if field not in scene:
                    issues.append(f"Ch{ch['chapter_number']} Scene{scene.get('scene_number','?')}: missing {field}")

if issues:
    print(f"\n❌ Found {len(issues)} scene field issues:")
    for i in issues[:5]:
        print(f"  {i}")
else:
    print(f"\n✅ All 120 scenes have all 8 required fields")

print(f"\nOutline validation complete!")
EOF
